INSERT INTO grammar.grammar_topics(slug,title,level,order_index,summary,guidance,learning_goals,rules,tips,source,source_metadata)
SELECT j->>'slug',j->>'title',j->>'level',(j->>'order')::integer,j->>'summary',j->>'guidance',ARRAY(SELECT jsonb_array_elements_text(j->'learningGoals')),j->'rules',ARRAY(SELECT jsonb_array_elements_text(j->'tips')),'seed','{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-possessive-s"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment.","contentHash":"96c6d65cc82b241ec16c30e21e2355867131e9c8c0230502f0315bae0cab7edb","sources":[{"id":"bc-possessive-s","title":"Possessive ’s","publisher":"British Council","url":"https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/possessive-s","use":"Guidance reference only; original contexts and exercises, no publisher question text reproduced","accessed":"2026-09-13"}]}'::jsonb FROM (SELECT '{"slug":"possessive-s","title":"Possessive ’s","level":"A1","order":13,"summary":"Show ownership with singular nouns, regular plurals and irregular plurals.","learningGoals":["One owner","Plural owners","Read the whole phrase"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"One owner","explanation":"Add apostrophe plus s to a singular owner noun in the forms practised here. The owner comes before the thing owned.","examples":["the explorer’s compass","the rabbit’s hutch"]},{"title":"Plural owners","explanation":"For a regular plural already ending in s, add only an apostrophe. For an irregular plural without final s, add apostrophe plus s.","examples":["the explorers’ compasses","the children’s drawings"]},{"title":"Read the whole phrase","explanation":"The owner phrase determines apostrophe placement. The owned object can itself be singular or plural. Names ending in s have additional conventions outside this bank.","examples":["one student’s notebooks","several students’ classroom"]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-possessive-s"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."}}'::jsonb j) payload
